static void _spec_pal_ensure_tmp_dir(const char* pc) {
    (void)pc;
}

static int _spec_pal_mkstemp_win_fallback(const char* tpl, char** buf_io, char* suffix, size_t suffix_cap) {
    (void)tpl; (void)buf_io; (void)suffix; (void)suffix_cap;
    return -1;
}
